test('a host enable saved in an idle transcript reaches the first user message after resume', async () => {
  const base = { model: { kind: 'builtin', provider: 'faux', id: 'faux-1' }, toolMode: 'dispatch' } as const
  const original = await fauxSession({ ...base, plugins: [units, makeWeather().plugin], systemPrompt: 'You are a test agent.' }, [])
  await original.session.enable('weather')
  const saved = JSON.parse(JSON.stringify(original.session.transcript()))

  const second = makeWeather()
  const resumed = await fauxSession({ ...base, plugins: [units, second.plugin], transcript: saved }, [reply('ok')])
  await resumed.session.prompt('Weather in Lisbon?')

  const users = resumed.requests[0]?.messages.filter((m) => m.role === 'user').map((m) => String(m.content))
  assert.equal(users?.length, 1)
  assert.match(users?.[0] ?? '', /^Weather in Lisbon\?\n\n[\s\S]*Weather data refreshes every 10 minutes\.[\s\S]*weather__get_weather: Current weather for a city\.\n {2}Parameters: /)
  assert.equal(second.calls.onEnable, 0)
})

test('streamed deltas never rejoin a split secret or split a character, and the text arrives whole', async () => {
  // Longer than the faux provider's largest chunk (20 characters), so every run splits it across deltas.
  const key = 'sk-station-0123456789abcdef'
  // The last cut falls 26 characters before the end, between the two halves of an emoji.
  const rain = `${'🌧'.repeat(20)}!`
  const { session } = await fauxSession({ model: { kind: 'builtin', provider: 'faux', id: 'faux-1' }, systemPrompt: 'Test.', plugins: [], secrets: { STATION_KEY: key } }, [
    reply(`The station key is ${key}, keep it safe. ${rain}`),
  ])
  const deltas: string[] = []
  session.subscribe((e) => {
    if (e.type === 'text') deltas.push(e.delta)
  })

  await session.prompt('Hi')

  assert.equal(deltas.join(''), `The station key is [REDACTED:STATION_KEY], keep it safe. ${rain}`)
  assert.deepEqual(deltas.filter((d) => /^[\uDC00-\uDFFF]|[\uD800-\uDBFF]$/.test(d)), [], 'no delta ends or starts inside a surrogate pair')
})

