function makeRedactor(secrets: Readonly<Record<string, string>>): (text: string) => string {
  const entries = Object.entries(secrets)
    .filter(([, value]) => value.length > 0)
    .sort(([, a], [, b]) => b.length - a.length)
  return (text) => entries.reduce((out, [name, value]) => out.split(value).join(`[REDACTED:${name}]`), text)
}

