test('a provider error ends the run with a redacted error result', async () => {
  const key = 'sk-provider-0123456789'
  const { session } = await fauxSession({ model: { kind: 'builtin', provider: 'faux', id: 'faux-1' }, systemPrompt: 'Test.', plugins: [], secrets: { PROVIDER_KEY: key } }, [
    () => fauxAssistantMessage('', { stopReason: 'error', errorMessage: `key ${key} was rejected` }),
  ])

  const result = await session.prompt('Hello?')

  assert.deepEqual(result, { stop: 'error', message: 'key [REDACTED:PROVIDER_KEY] was rejected', turns: 1 })
  assert.ok(!JSON.stringify(session.transcript()).includes(key))
})

test('the host signal cuts the model off, and max turns stops a model that keeps calling tools', async () => {
  const controller = new AbortController()
  const weather = makeWeather()
  const abortThenCall: Step = () => {
    controller.abort()
    return fauxAssistantMessage(fauxToolCall('weather__get_weather', { city: 'Lisbon' }), { stopReason: 'toolUse' })
  }
  const aborting = await fauxSession({ model: { kind: 'builtin', provider: 'faux', id: 'faux-1' }, systemPrompt: 'Test.', plugins: [units, weather.plugin], enabled: ['weather'] }, [abortThenCall, reply('late')])
  assert.equal((await aborting.session.prompt('Hello?', { signal: controller.signal })).stop, 'aborted')
  assert.equal(weather.calls.getWeather, 0, 'the aborted response never ran its tool call')

  const convert = toolCall('units__c_to_f', { celsius: '17' })
  const looping = await fauxSession({ model: { kind: 'builtin', provider: 'faux', id: 'faux-1' }, systemPrompt: 'Test.', plugins: [units], enabled: ['units'], maxTurns: 2 }, [convert, convert, convert])
  assert.equal((await looping.session.prompt('Convert forever.')).stop, 'max_turns')
  assert.equal(looping.callCount(), 2)
})

