  let release = () => {}
  const held = new Promise<void>((resolve) => (release = resolve))
  const { session } = await fauxSession({ model: { kind: 'builtin', provider: 'faux', id: 'faux-1' }, systemPrompt: 'Test.', plugins: [] as Plugin[] }, [
